class PedidoInvalidoError(Exception):
    """Erro para pedidos com dados inválidos."""


class PedidoNaoEncontradoError(Exception):
    """Erro quando o pedido não existe."""


def validar_pedido_id(pedido_id: str) -> str:
    """Valida o formato do número do pedido antes de consultar."""
    if not isinstance(pedido_id, str):
        raise PedidoInvalidoError("O número do pedido deve ser um texto.")

    pedido_id = pedido_id.strip()

    if not pedido_id:
        raise PedidoInvalidoError("O número do pedido não pode ser vazio.")

    if not pedido_id.isalnum():
        raise PedidoInvalidoError("O número do pedido contém caracteres inválidos.")

    return pedido_id


def consultar_pedido(pedido_id: str) -> dict:
    """Consulta um pedido, tratando erros de validação e de busca."""
    try:
        pedido_valido = validar_pedido_id(pedido_id)
        resultado = buscar_no_sistema(pedido_valido)  # sua função de busca

        if resultado is None:
            raise PedidoNaoEncontradoError(f"Pedido {pedido_valido} não encontrado.")

        return {"ok": True, "dados": resultado}

    except PedidoInvalidoError as e:
        return {"ok": False, "erro": "validacao", "mensagem": str(e)}

    except PedidoNaoEncontradoError as e:
        return {"ok": False, "erro": "nao_encontrado", "mensagem": str(e)}

    except Exception as e:
        # Captura falhas inesperadas (ex.: conexão com o sistema) sem derrubar o programa
        return {"ok": False, "erro": "interno", "mensagem": "Erro inesperado. Tente novamente."}


def buscar_no_sistema(pedido_id: str):
    """Função fictícia só para o exemplo funcionar."""
    base = {"12345": {"status": "enviado"}}
    return base.get(pedido_id)


# Exemplos de uso
print(consultar_pedido("12345"))    # encontrado
print(consultar_pedido("99999"))    # não encontrado
print(consultar_pedido("  "))       # validação falha
print(consultar_pedido("12-34"))    # caractere inválido
```

Pontos principais:

1. **Validação separada**: a função `validar_pedido_id` cuida só do formato, antes de qualquer busca.
