```python
class PedidoError(Exception):
    """Exceção base para erros de pedidos."""
    codigo = "PEDIDO_ERRO"

    def __init__(self, mensagem: str):
        super().__init__(mensagem)
        self.mensagem = mensagem


class PedidoInvalidoError(PedidoError):
    codigo = "PEDIDO_INVALIDO"


class PedidoNaoEncontradoError(PedidoError):
    codigo = "PEDIDO_NAO_ENCONTRADO"


class ValidadorPedido:
    def validar(self, pedido: dict) -> None:
        if not pedido.get("id"):
            raise PedidoInvalidoError("ID do pedido é obrigatório.")
        if pedido.get("valor", 0) <= 0:
            raise PedidoInvalidoError("O valor do pedido deve ser maior que zero.")
        if not pedido.get("itens"):
            raise PedidoInvalidoError("O pedido precisa ter ao menos um item.")


class ServicoPedido:
    def __init__(self, validador: ValidadorPedido):
        self.validador = validador

    def processar(self, pedido: dict) -> str:
        try:
            self.validador.validar(pedido)
            # regra de negócio aqui
            return "Pedido processado com sucesso."
        except PedidoInvalidoError as e:
            return f"[{e.codigo}] {e.mensagem}"
        except PedidoError as e:
            return f"[{e.codigo}] Erro no pedido: {e.mensagem}"
        except Exception:
            # registrar o erro em log e retornar mensagem genérica
            return "[ERRO_INTERNO] Ocorreu um erro inesperado. Tente novamente."


# Exemplo de uso
servico = ServicoPedido(ValidadorPedido())
print(servico.processar({"id": "", "valor": 100, "itens": ["A"]}))
# [PEDIDO_INVALIDO] ID do pedido é obrigatório.
```

Pontos principais:
- Exceções específicas por tipo de erro, com herança de uma exceção base.
- Validação separada da regra de negócio.
- Captura do mais específico para o mais genérico.
- Erros inesperados são registrados em log e o usuário recebe mensagem genérica, sem detalhes internos.

